func (q *Queries) UpsertMediaRef(ctx context.Context, arg UpsertMediaRefParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertMediaRef,
		arg.MediaAssetID,
		arg.OwnerUserID,
		arg.RefType,
		arg.RefID,
		arg.BoardID,
		arg.TaskID,
		arg.Role,
		arg.InputIndex,
		arg.Metadata,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
